def ok(s):
    stack = []
    for ch in s:
        if ch == '(':
            stack.append(ch)
        elif ch == ')':
            if not stack:
                return False
            stack.pop()
    return len(stack) == 0
print(ok('(())()'))

tokens = [4, 6, '+', 3, '*']
st = []
for t in tokens:
    if t == '+':
        b = st.pop(); a = st.pop(); st.append(a + b)
    elif t == '*':
        b = st.pop(); a = st.pop(); st.append(a * b)
    else:
        st.append(t)
print(st[-1])

def bal(s):
    pairs = {')': '(', ']': '['}
    st = []
    for ch in s:
        if ch in '([':
            st.append(ch)
        elif ch in pairs:
            if not st or st.pop() != pairs[ch]:
                return False
    return not st
print(bal('([)]'), bal('([])'))

nums = [2, 5, 1, 6]
stack = []
out = []
for n in reversed(nums):
    while stack and stack[-1] <= n:
        stack.pop()
    if not stack:
        out.append(-1)
    else:
        out.append(stack[-1])
    stack.append(n)
print(out)
